// Generated by scripts/font-roles.py from the face files font-roles.mjs names: each face's code points as ranges
// (start, end, inclusive), its metrics in its own units (hhea's ascent and descent, the descent positive below the
// baseline; small capitals by GSUB smcp; the file's SHA-256), and the releases the files come from. Not edited by
// hand: re-run the script (its header says how)

// a face's ranges from their text: per range, the gap after the previous range's end and its length, in base 36
const ranges = text => {
  const parts = text.trim().split(/\s+/), out = []
  let end = -1
  for (let i = 0; i + 1 < parts.length; i += 2) {
    const start = end + 1 + Number.parseInt(parts[i], 36)
    end = start + Number.parseInt(parts[i + 1], 36)
    out.push(start, end)
  }
  return Object.freeze(out)
}
